namespace FScript.Tests

module TaskLibraryCases =
    let successes =
        [ "pipeline continuation", "Task.fromResult 41 |> Task.continueWith (fun value -> value+1) |> Task.await", "42"
          "pipeline all", "[Task.fromResult 20;Task.fromResult 22] |> Task.whenAll (List.fold (fun total value -> total+value) 0) |> Task.await", "42"
          "pipeline any", "let tasks=[Task.fromResult 41;Task.fromResult 0]\nlet result=tasks |> Task.whenAny (fun value -> value+1) |> Task.await\nTask.awaitAll tasks |> ignore\nresult", "42"
          "reusable continuation", "let increment=Task.continueWith (fun value -> value+1)\nlet first=Task.fromResult 20 |> increment\nlet second=Task.fromResult 20 |> increment\n[first;second] |> Task.whenAll (List.fold (fun total value -> total+value) 0) |> Task.await", "42"
          "immediate function application", "Task.await (Task.fromResult (fun value -> value+2)) 40", "42"
          "completed list", "Task.fromResult [1;2] |> Task.await", "[1;2]"
          "list result continuation", "Task.continueWith (List.map (fun value -> value+1)) (Task.fromResult [1;2]) |> Task.await", "[2;3]"
          "all list results", "Task.whenAll (List.collect (fun values -> values)) [Task.fromResult [1];Task.fromResult [2]] |> Task.await", "[1;2]"
          "function result", "let add=Task.continueWith (fun value -> fun other -> value+other) (Task.fromResult 2) |> Task.await\nadd 40", "42"
          "completed value", "Task.fromResult 42 |> Task.await", "42"
          "zero delay", "Task.delay 0 |> Task.await", "()"
          "delay and continuation", "Task.continueWith (fun () -> 42) (Task.delay 1) |> Task.await", "42"
          "continuation value", "Task.continueWith (fun value -> value+1) (Task.fromResult 41) |> Task.await", "42"
          "ordered all results", "let first=Task.continueWith (fun () -> 1) (Task.delay 5)\nlet second=Task.fromResult 2\nTask.whenAll (fun values -> values) [first;second] |> Task.await", "[1;2]"
          "all transformed", "Task.whenAll (List.fold (fun total value -> total+value) 0) [Task.fromResult 20;Task.fromResult 22] |> Task.await", "42"
          "empty all", "Task.whenAll List.length (List.init 0 Task.fromResult) |> Task.await", "0"
          "await all", "Task.awaitAll [Task.fromResult 1;Task.fromResult 2]", "[1;2]"
          "empty await all", "Task.awaitAll (List.init 0 Task.fromResult)", "[]"
          "first already completed", "let tasks=[Task.fromResult 1;Task.fromResult 2]\nlet result=Task.whenAny (fun value -> value+40) tasks |> Task.await\nTask.awaitAll tasks |> ignore\nresult", "41"
          "unit any", "let tasks=[Task.fromResult ();Task.fromResult ()]\nlet result=Task.whenAny (fun () -> 42) tasks |> Task.await\nTask.awaitAll tasks |> ignore\nresult", "42"
          "tagged heterogeneous results", "type Completion = Text of string | Number of int\nlet text=Task.continueWith Text (Task.fromResult \"ok\")\nlet number=Task.continueWith Number (Task.fromResult 7)\nlet result=Task.whenAny (fun completed -> match completed with | Text value -> value | Number value -> Int.toString value) [text;number] |> Task.await\nTask.awaitAll [text;number] |> ignore\nresult = \"ok\" || result = \"7\"", "true"
          "nested continuation", "Task.continueWith (fun value -> Task.fromResult (value+1)) (Task.fromResult 1) |> Task.await |> Task.await", "2"
          "nested spawn", "Task.spawn (fun () -> Task.fromResult 42) |> Task.await |> Task.await", "42"
          "nested completed value", "Task.fromResult (Task.fromResult 42) |> Task.await |> Task.await", "42"
          "nested all", "Task.whenAll (fun values -> Task.fromResult values) [Task.fromResult 1] |> Task.await |> Task.await", "[1]"
          "nested any", "Task.whenAny (fun value -> Task.fromResult value) [Task.fromResult 1] |> Task.await |> Task.await", "1"
          "partial continuation", "let ready=Task.fromResult 41\nlet plusOne=Task.continueWith (fun value -> value+1)\nready |> plusOne |> Task.await", "42"
          "captured callback", "let offset=40\nTask.continueWith (fun value -> value+offset) (Task.fromResult 2) |> Task.await", "42"
          "chained continuations", "let first=Task.continueWith (fun value -> value+1) (Task.fromResult 1)\nTask.continueWith (fun value -> value+40) first |> Task.await", "42"
          "zero delay handles remain distinct", "let first=Task.delay 0\nlet second=Task.delay 0\nTask.awaitAll [first;second] |> List.length", "2"
          "implicit completed", "Task.fromResult 42 |> ignore", "()"
          "implicit delay", "Task.delay 1 |> ignore", "()"
          "implicit continuation", "Task.continueWith (fun value -> value+1) (Task.fromResult 1) |> ignore", "()"
          "implicit nested result", "Task.spawn (fun () -> Task.delay 1) |> ignore", "()"
          "implicit loser", "Task.whenAny (fun value -> value) [Task.fromResult 1;Task.fromResult 2] |> Task.await", "1"
          "unobserved duplicate value", "let first=Task.fromResult 1\nlet second=Task.fromResult 1\nTask.await first", "1"
          "duplicate handles", "let value=Task.fromResult 21\nTask.whenAll (List.fold (fun sum value -> sum+value) 0) [value;value] |> Task.await", "42" ]
    let failures =
        [ "negative delay", "Task.delay (0 - 1) |> Task.await", "0..2147483647"
          "delay overflow", "Task.delay 2147483648 |> Task.await", "0..2147483647"
          "empty any", "Task.whenAny (fun value -> value+1) (List.init 0 Task.fromResult) |> Task.await", "non-empty"
          "failed source", "Task.continueWith (fun (value: int) -> value+1) (Task.spawn (fun () -> raise \"source-failed\")) |> Task.await", "source-failed"
          "implicit failure", "Task.spawn (fun () -> if true then raise \"background-failed\" else 0) |> ignore\n42", "background-failed"
          "implicit loser failure", "let winner=Task.fromResult 42\nlet loser=Task.spawn (fun () ->\n  Task.await (Task.delay 5)\n  if true then raise \"loser-failed\" else 0)\nTask.whenAny (fun value -> value) [winner;loser] |> Task.await", "loser-failed"
          "collected failures", "let first=Task.spawn (fun () -> if true then raise \"failure-one\" else 0)\nlet second=Task.spawn (fun () ->\n  Task.await (Task.delay 5)\n  if true then raise \"failure-two\" else 0)\n42", "failure-two"
          "failed callback", "Task.continueWith (fun value -> if value=1 then raise \"callback-failed\" else 0) (Task.fromResult 1) |> Task.await", "callback-failed" ]
